    const parts = unsigned.split(separator);
    const groupedInteger = parts.length > 2 && parts.slice(1).every((part) => part.length === 3);
    if (groupedInteger) normalized = parts.join('');
    else normalized = parts.slice(0, -1).join('') + '.' + parts.at(-1);
  }

  const value = Number((negative ? '-' : '') + normalized);
  return Number.isFinite(value) ? value : null;
}

function roundVisibleNumbers(markup) {
  return markup.replace(/(-?\d{1,3}(?:[.,]\d{3})+(?:[.,]\d+)?|-?\d+[.,]\d{3,})(%?)/g, (full, numeric, suffix) => {
    const value = parseDisplayNumber(numeric);
    return value === null ? full : numberFormat.format(value) + suffix;
