function parseToken(token) {
  const negative = token.startsWith('-');
  const source = negative ? token.slice(1) : token;
  const comma = source.lastIndexOf(',');
  const dot = source.lastIndexOf('.');
  const parts = source.split(/[.,]/);
  let normalized;

  if (comma >= 0 && dot >= 0) {
    const decimalAt = Math.max(comma, dot);
    normalized = source.slice(0, decimalAt).replace(/[.,]/g, '') + '.' + source.slice(decimalAt + 1);
  } else {
    const separator = comma >= 0 ? ',' : '.';
    const isGroupedInteger = parts.length > 1 && parts.slice(1).every((part) => part.length === 3);
    normalized = isGroupedInteger ? parts.join('') : parts.slice(0, -1).join('') + '.' + parts.at(-1);
  }

  const value = Number((negative ? '-' : '') + normalized);
  return Number.isFinite(value) ? value : null;
}

function roundMarkup(markup) {
  return markup.replace(/(-?\d+(?:[.,]\d+)+)(%?)(?![\d.,])/g, (full, token, suffix) => {
    const value = parseToken(token);
    return value === null ? full : formatter.format(value) + suffix;
  });
}

html = html.replace(/(<main class="deck">)([\s\S]*?)(<\/main>)/, (full, opening, body, closing) => {
